files.content:
:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --bar: #4e9af1;
  --bar-compare: #f2c94c;
  --text: #f0f0f5;
  --accent: #6c63ff;
  --accent-hover: #8a84ff;
  --accent-active: #544fd9;
  --focus: #f2c94c;
  --radius: 8px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  padding: 16px;
}

.card {
  background: var(--card);
  padding: 32px;
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  width: 100%;
  max-width: 640px;
  text-align: center;
}

h1 {
  margin: 0 0 8px;
  font-size: 1.75rem;
  font-weight: 700;
}

.subtitle {
  margin: 0 0 24px;
  font-size: 1rem;
  opacity: 0.8;
}

.bars {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 8px;
  height: 240px;
  margin-bottom: 24px;
  padding: 0 4px;
}

.bar {
  flex: 1;
  max-width: 48px;
  background: var(--bar);
  border-radius: 4px 4px 0 0;
  transition: height 0.2s ease, background 0.2s ease;
  min-height: 8px;
}

.bar.compare {
  background: var(--bar-compare);
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: none;
  border-radius: var(--radius);
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  min-width: 120px;
}

button:hover {
  background: var(--accent-hover);
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button:active {
  background: var(--accent-active);
  transform: scale(0.97);
}

.message {
  min-height: 1.5em;
  margin: 0;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--bar-compare);
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .bars {
    height: 180px;
    gap: 4px;
  }
  button {
    padding: 10px 16px;
    min-width: 100px;
  }
}

(function () {
  'use strict';

  var NUM_BARS = 10;
  var barsContainer = document.getElementById('bars');
  var shuffleBtn = document.getElementById('shuffle');
  var stepBtn = document.getElementById('step');
  var messageEl = document.getElementById('message');

  var values = [];
  var barEls = [];
  var i = 0;
  var j = 0;
  var sorted = false;

  function randomValues() {
    var arr = [];
    for (var k = 0; k < NUM_BARS; k++) {
      // heights between 10 and 100, unique-ish
      arr.push(Math.floor(Math.random() * 91) + 10);
    }
    return arr;
  }

  function render() {
    barsContainer.innerHTML = '';
    barEls = [];
    for (var k = 0; k < values.length; k++) {
      var bar = document.createElement('div');
      bar.className = 'bar';
      bar.style.height = values[k] + '%';
      bar.setAttribute('data-index', k);
      bar.setAttribute('aria-label', 'Bar ' + (k + 1) + ': ' + values[k]);
      barsContainer.appendChild(bar);
      barEls.push(bar);
    }
  }

  function clearHighlights() {
    for (var k = 0; k < barEls.length; k++) {
      barEls[k].classList.remove('compare');
    }
  }

  function highlight(a, b) {
    clearHighlights();
    if (barEls[a]) barEls[a].classList.add('compare');
    if (barEls[b]) barEls[b].classList.add('compare');
  }

  function shuffle() {
    values = randomValues();
    i = 0;
    j = 0;
    sorted = false;
    messageEl.textContent = '';
    render();
    clearHighlights();
  }

  function step() {
    if (sorted) return;

    if (i >= values.length - 1) {
      sorted = true;
      clearHighlights();
      messageEl.textContent = 'Sorted! The bars are in order.';
      return;
    }

    // one comparison at (j, j+1)
    highlight(j, j + 1);

    if (values[j] > values[j + 1]) {
      var tmp = values[j];
      values[j] = values[j + 1];
      values[j + 1] = tmp;
      // update DOM heights after swap
      barEls[j].style.height = values[j] + '%';
      barEls[j].setAttribute('aria-label', 'Bar ' + (j + 1) + ': ' + values[j]);
      barEls[j + 1].style.height = values[j + 1] + '%';
      barEls[j + 1].setAttribute('aria-label', 'Bar ' + (j + 2) + ': ' + values[j + 1]);
    }

    j++;
    if (j >= values.length - 1 - i) {
      j = 0;
      i++;
      if (i >= values.length - 1) {
        sorted = true;
        clearHighlights();
        messageEl.textContent = 'Sorted! The bars are in order.';
      }
    }
  }

  function init() {
    values = randomValues();
    render();
    i = 0;
    j = 0;
    sorted = false;
    messageEl.textContent = '';

    shuffleBtn.addEventListener('click', shuffle);
    stepBtn.addEventListener('click', step);
  }

  init();
})();
